import hashlib, json, subprocess
from pathlib import Path
out=Path('validation/2026-11-07-plan-plan-local-reward-live-console')
before=json.loads((out/'preservation-before.json').read_text())
roots=['reference/v0.3-rc1','.aiops','.github','docs/tasks']
paths=[p for root in roots for p in Path(root).rglob('*') if p.is_file()]
paths += [Path('runtime/crates/kix-kernel/src/lib.rs'),Path('runtime/crates/kix-kernel/tests/quarantine_capacity.rs')]
allowed={'reward_console.py','test_reward_console.py','test_reward_console_subprocess.py','README.md'}
